var minOperations = function(grid, x) {
    const arr = grid.reduce((acc, el) => acc.concat(el), []);
    const remainder = grid[0][0] % x;

    if (arr.some((el) => el % x !== remainder)) {
        return -1;
    }

    arr.sort((a, b) => a - b);

    const mid = Math.floor(arr.length / 2);

    if ((arr.length & 1) || arr[mid - 1] === arr[mid]) {
